SELECT EXISTS (
    SELECT 1 FROM document_import_task WHERE document_id=#{id}
    AND (status IN ('PENDING','RUNNING') OR (status='FAILED' AND next_retry_at IS NOT NULL))
)

SELECT DISTINCT ON (document_id) id,document_id,index_version_id,status,created_at,updated_at FROM document_import_task WHERE document_id IN
#{id}
ORDER BY document_id,created_at DESC,id DESC
